class Solution {
public:
    int countMonobitIntegers(long long low, long long high) {
        int count = 0;
        long long p = 1;
        while (p <= high) {
            if (p >= low) count++;
            if (p > high / 2) break;
            p <<= 1;
        }
        return count;
    }
};

class Solution {
    public int countMonobitIntegers(long low, long high) {
        int count = 0;
        long p = 1;
        while (p <= high) {
            if (p >= low) count++;
            if (p > high / 2) break;
            p <<= 1;
        }
        return count;
    }
}

function countMonobitIntegers(low, high) {
    let count = 0;
    let p = 1n;
    const l = BigInt(low), h = BigInt(high);
    while (p <= h) {
        if (p >= l) count++;
        p <<= 1n;
    }
    return count;
}
